insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-239', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'The Henderson–Hasselbalch equation for an acidic buffer is', '["$\\mathrm{pH} = \\mathrm{p}K_a + \\log([\\mathrm{salt}]/[\\mathrm{acid}])$","$\\mathrm{pH} = \\mathrm{p}K_a - \\log([\\mathrm{salt}]/[\\mathrm{acid}])$","$\\mathrm{pH} = \\mathrm{p}K_a + [\\mathrm{salt}]$","$\\mathrm{pH} = 14 - \\mathrm{p}K_a$"]'::jsonb, 0, 'From Ka = [H+][salt]/[acid] one obtains pH = pKa + log([salt]/[acid]).', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
